WITH valid AS (SELECT *, CASE WHEN discount_pct >= 0.36 THEN 'High' WHEN discount_pct >= 0.18 THEN 'Medium' ELSE 'Low' END AS discount_pct_tier, ROUND(discount_pct, 1) AS discount_pct_rounded, COALESCE(channel, 'N/A') AS channel_filled FROM promotions WHERE starts_on >= DATE '2023-06-04' AND discount_pct < 0.32) SELECT * FROM (SELECT channel, promo_code, discount_pct FROM valid) src PIVOT (AVG(discount_pct) AS amount, COUNT(1) AS item_count FOR promo_code IN ('WELCOME5', 'SPRING10'))
